import { useState, FormEvent } from 'react';
import {
  Form,
  FormField,
  TextInput,
  Select,
  SelectOption,
  Switch,
  Button,
} from '@jinx-ui/react';

type Language = 'ru' | 'en';

interface ProfileSettings {
  name: string;
  language: Language;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
}

const ProfileSettingsForm = ({ onSave }: ProfileSettingsFormProps) => {
  const [name, setName] = useState('');
  const [language, setLanguage] = useState<Language>('ru');
  const [emailNotifications, setEmailNotifications] = useState(false);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <Form className="jx-stack" onSubmit={handleSubmit}>
      <FormField label="Имя" htmlFor="profile-name">
        <TextInput
          id="profile-name"
          value={name}
          onChange={(event) => setName(event.target.value)}
          placeholder="Введите имя"
        />
      </FormField>

      <FormField label="Язык интерфейса" htmlFor="profile-language">
        <Select
          id="profile-language"
          value={language}
          onChange={(value) => setLanguage(value as Language)}
        >
          <SelectOption value="ru">Русский</SelectOption>
          <SelectOption value="en">Английский</SelectOption>
        </Select>
      </FormField>

      <FormField label="Уведомления на почту" htmlFor="profile-email-notifications">
        <Switch
          id="profile-email-notifications"
          checked={emailNotifications}
          onChange={(checked) => setEmailNotifications(checked)}
        />
      </FormField>

      <Button type="submit" variant="primary">
        Сохранить
      </Button>
    </Form>
  );
};

export default ProfileSettingsForm;

